def draw_grid(grid):
    n = len(grid)
    m = len(grid[0])

    def is_valid_star(x, y, s):
        if x - s < 1 or x + s > n or y - s < 1 or y + s > m:
            return False
        for i in range(s):
            if grid[x-s+i][y-i] != '.' or grid[x+s-i][y-i] != '.' or grid[x-s+i][y+i] != '.' or grid[x+s-i][y+i] != '.':
                return False
        if grid[x][y-s] != '*' or grid[x][y+s] != '*' or grid[x-s][y] != '*' or grid[x+s][y] != '*':
            return False
        return True

    def place_star(x, y, s):
        for i in range(2*s+1):
            for j in range(2*s+1):
                if (i == s and abs(j - s) <= s) or (j == s and abs(i - s) <= s):
                    grid[x+s-i][y+s-j] = '.'

    count = 0
    stars = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                for s in range(1, min(i+1, j+1, n-i, m-j)+1):
                    if is_valid_star(i, j, s):
                        place_star(i, j, s)
                        count += 1
                        stars.append((i, j, s))
                        break

    if sum(len(row.count('*')) for row in grid) != 0:
        return '-1'

    return f'{count}\n' + '\n'.join(f'{x} {y} {s}' for x, y, s in stars)

